function verifyCableTerminationExists(cable, cable_end, id, termination_id, termination_type) {
  var url = "/api/dcim/cable-terminations/";
  var description = "Verify CableTermination with id " + id + " exists";
  svc.get(url, {
    expectedResponseCodes: [200],
    parameters: { description: description },
    callback: function(response) {
      var items = JSON.parse(response.body);
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          if (String(items[i].id) === String(id)) {
            return pvg.success("CableTermination exists");
          }
        }
      }
      return pvg.fail("Expected CableTermination to exist but it does not");
    }
  });
}

