function matchAddedRack(airflow, asset_tag, comments, custom_fields, desc_units, description, facility_id, form_factor, id, location, max_weight, mounting_depth, name, outer_depth, outer_height, outer_unit, outer_width, rack_type, role, serial, site, starting_unit, status, tags, tenant, u_height, weight, weight_unit, width) {
  var expectedDesc = "Create rack " + name + " with id " + id;
  return matchSuccess(expectedDesc);
}

function waitForAnyRackAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Create\ rack\ (.+)\ with\ id\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Create\ rack\ (.+)\ with\ id\ (.+)$/);
  var captures = m.slice(1);
  var names = ["name", "id"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

function getRackAddedEvent(keyVal) {
  return bp.EventSet("AddRack:" + keyVal, function(e) {
    if (!e.data || !e.data.parameters) return false;
    return String(e.data.parameters.id) === String(keyVal);
  });
}

function matchAnyRackAdded() {
  return bp.EventSet("matchAnyRackAdded", function(e) {
    return e.name.startsWith("Done: ") && e.data && e.data.id !== undefined && e.name.indexOf("Create rack") > -1;
  });
}

function waitForRackAdded(airflow, asset_tag, comments, custom_fields, desc_units, description, facility_id, form_factor, id, location, max_weight, mounting_depth, name, outer_depth, outer_height, outer_unit, outer_width, rack_type, role, serial, site, starting_unit, status, tags, tenant, u_height, weight, weight_unit, width) {
  var expectedDesc = "Create rack " + name + " with id " + id;
  waitFor(matchSuccess(expectedDesc));
}

function matchDeletedRack(airflow, asset_tag, comments, custom_fields, desc_units, description, facility_id, form_factor, id, location, max_weight, mounting_depth, name, outer_depth, outer_height, outer_unit, outer_width, rack_type, role, serial, site, starting_unit, status, tags, tenant, u_height, weight, weight_unit, width) {
  var expectedDesc = "Delete rack with id " + id;
  return bp.EventSet("matchDeletedRack", function(e) {
      return !!(e.data && e.data.parameters && e.data.parameters.description === expectedDesc);
  });
}

function waitForAnyRackDeleted() {
  var ev = waitFor(matchesDescriptionRegex(/^Delete\ rack\ with\ id\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Delete\ rack\ with\ id\ (.+)$/);
  var captures = m.slice(1);
  var names = ["id"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

