function waitForAnyCustomLinkAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Create\ custom\ link\ (.+)\ with\ id\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Create\ custom\ link\ (.+)\ with\ id\ (.+)$/);
  var captures = m.slice(1);
  var names = ["name", "id"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

function getCustomLinkAddedEvent(keyVal) {
  return bp.EventSet("AddCustomLink:" + keyVal, function(e) {
    if (!e.data || !e.data.parameters) return false;
    return String(e.data.parameters.id) === String(keyVal);
  });
}

function matchAnyCustomLinkAdded() {
  return bp.EventSet("matchAnyCustomLinkAdded", function(e) {
    return e.name.startsWith("Done: ") && e.data && e.data.id !== undefined && e.name.indexOf("Create custom link") > -1;
  });
}

