function waitForAnyIPAddressAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Create\ ip\ address\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Create\ ip\ address\ (.+)$/);
  var captures = m.slice(1);
  var names = ["address"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

function getIPAddressAddedEvent(keyVal) {
  return bp.EventSet("AddIPAddress:" + keyVal, function(e) {
    if (!e.data || !e.data.parameters) return false;
    return String(e.data.parameters.id) === String(keyVal);
  });
}

function matchAnyIPAddressAdded() {
  return bp.EventSet("matchAnyIPAddressAdded", function(e) {
    return e.name.startsWith("Done: ") && e.data && e.data.id !== undefined && e.name.indexOf("Create ip address") > -1;
  });
}

