function waitForAnyPrefixAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Create\ prefix$/));
  var m = ev.data.parameters.description.match(/^Create\ prefix$/);
  var captures = m.slice(1);
  var names = [];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

