function verifyDataSourceExists(comments, custom_fields, description, enabled, id, ignore_rules, name, parameters, source_url, sync_interval, type) {
  var url = "/api/core/data-sources/";
  var description = "Verify DataSource with id " + id + " exists";
  svc.get(url, {
    expectedResponseCodes: [200],
    parameters: { description: description },
    callback: function(response) {
      var items = JSON.parse(response.body);
      if (Array.isArray(items)) {
        for (var i = 0; i < items.length; i++) {
          if (String(items[i].id) === String(id)) {
            return pvg.success("DataSource exists");
          }
        }
      }
      return pvg.fail("Expected DataSource to exist but it does not");
    }
  });
}

