function matchAddedDataSource(comments, custom_fields, description, enabled, id, ignore_rules, name, parameters, source_url, sync_interval, type) {
  var expectedDesc = "Create data source " + name + " with id " + id;
  return matchSuccess(expectedDesc);
}

function waitForAnyDataSourceAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Create\ data\ source\ (.+)\ with\ id\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Create\ data\ source\ (.+)\ with\ id\ (.+)$/);
  var captures = m.slice(1);
  var names = ["name", "id"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

function getDataSourceAddedEvent(keyVal) {
  return bp.EventSet("AddDataSource:" + keyVal, function(e) {
    if (!e.data || !e.data.parameters) return false;
    return String(e.data.parameters.id) === String(keyVal);
  });
}

function matchAnyDataSourceAdded() {
  return bp.EventSet("matchAnyDataSourceAdded", function(e) {
    return e.name.startsWith("Done: ") && e.data && e.data.id !== undefined && e.name.indexOf("Create data source") > -1;
  });
}

function waitForDataSourceAdded(comments, custom_fields, description, enabled, id, ignore_rules, name, parameters, source_url, sync_interval, type) {
  var expectedDesc = "Create data source " + name + " with id " + id;
  waitFor(matchSuccess(expectedDesc));
}

function matchDeletedDataSource(comments, custom_fields, description, enabled, id, ignore_rules, name, parameters, source_url, sync_interval, type) {
  var expectedDesc = "Delete data source with id " + id;
  return bp.EventSet("matchDeletedDataSource", function(e) {
      return !!(e.data && e.data.parameters && e.data.parameters.description === expectedDesc);
  });
}

function waitForAnyDataSourceDeleted() {
  var ev = waitFor(matchesDescriptionRegex(/^Delete\ data\ source\ with\ id\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Delete\ data\ source\ with\ id\ (.+)$/);
  var captures = m.slice(1);
  var names = ["id"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

