function waitForAnyIKEProposalAdded() {
  var ev = waitFor(matchesDescriptionRegex(/^Create\ ike\ proposal\ with\ id\ (.+)$/));
  var m = ev.data.parameters.description.match(/^Create\ ike\ proposal\ with\ id\ (.+)$/);
  var captures = m.slice(1);
  var names = ["id"];
  var obj = {};
  for (var i = 0; i < names.length; i++) {
    obj[names[i]] = (i < captures.length) ? captures[i] : undefined;
  }
  return obj;
}

function getIKEProposalAddedEvent(keyVal) {
  return bp.EventSet("AddIKEProposal:" + keyVal, function(e) {
    if (!e.data || !e.data.parameters) return false;
    return String(e.data.parameters.id) === String(keyVal);
  });
}

function matchAnyIKEProposalAdded() {
  return bp.EventSet("matchAnyIKEProposalAdded", function(e) {
    return e.name.startsWith("Done: ") && e.data && e.data.id !== undefined && e.name.indexOf("Create ike proposal") > -1;
  });
}

